def table(title,headers,rows,widths=None,fs=10.5):
 caption(title,'table');t=d.add_table(rows=1, cols=len(headers));t.autofit=False
 if widths:
  for c,w in zip(t.columns,widths):c.width=Cm(w)
 for c,txt in zip(t.rows[0].cells,headers):c.text=txt
 for row in rows:
  for c,txt in zip(t.add_row().cells,row):c.text=str(txt)
 for ri,row in enumerate(t.rows):
  pr=row._tr.get_or_add_trPr();no=OxmlElement('w:cantSplit');pr.append(no)
  if ri==0:pr.append(OxmlElement('w:tblHeader'))
  for ci,c in enumerate(row.cells):
   if widths:c.width=Cm(widths[ci])
   cp=c._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
   for side in ['top','left','bottom','right']:
    z=OxmlElement('w:'+side);z.set(qn('w:val'),'single');z.set(qn('w:sz'),'4');z.set(qn('w:color'),'D9D9D9');b.append(z)
   cp.append(b)
   mar=OxmlElement('w:tcMar')
   for side in ['top','bottom','left','right']:
    z=OxmlElement('w:'+side);z.set(qn('w:w'),'65');z.set(qn('w:type'),'dxa');mar.append(z)
   cp.append(mar)
   if ri==0:
    sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'EEEEEE');cp.append(sh)
   for q in c.paragraphs:
    q.paragraph_format.space_after=Pt(2);q.paragraph_format.line_spacing=1.1
    for r in q.runs:r.font.size=Pt(fs);r.bold=ri==0
 return t
